/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
Keil uVision is an integrated development environment (IDE) that provides
code editing, compilation, simulation, and debugging for ARM-based
microcontrollers like the LPC2148. Flash Magic is a dedicated In-System
Programming (ISP) tool used to burn compiled Intel HEX binaries into the
LPC2148 on-chip flash memory via UART serial interface. The toolchain
workflow requires configuring the LPC2148 device database, selecting the
ARM target oscillator frequency (12.0 MHz), generating a HEX binary via
Armcc / Armclang, and flashing over COM port with ISP handshaking.
============================================================================
*/

/*
 * Experiment 14: Interfacing of LED with Embedded Core (LPC 2148)
 * Demonstrates Port 0 GPIO Pin Configuration, Set, Clear, and Patterns
 */

#include <LPC214x.h>

#define LED_PINS (0xFF << 10)   // P0.10 to P0.17 for 8 LEDs

void delay(unsigned int count) {
    unsigned int i, j;
    for (i = 0; i < count; i++) {
        for (j = 0; j < 6000; j++) {
            #ifdef __GNUC__
            __asm__("nop");
            #endif
        }
    }
}

void led_counter(void) {
    unsigned int count;
    for (count = 0; count < 256; count++) {
        IO0CLR = LED_PINS;
        IO0SET = (count << 10) & LED_PINS;
        delay(100);
    }
}

int main(void) {
    // Select GPIO function for P0.10 - P0.17
    PINSEL0 &= ~0xFFFF0000;

    // Configure P0.10 - P0.17 as output
    IO0DIR |= LED_PINS;

    // Initially turn off all LEDs
    IO0CLR = LED_PINS;

    while (1) {
        // Pattern 1: All ON / All OFF
        IO0SET = LED_PINS;
        delay(300);
        IO0CLR = LED_PINS;
        delay(300);

        // Pattern 2: Binary Ripple Counter
        led_counter();
    }
    return 0;
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
The LPC2148 is an ARM7TDMI-S based 32-bit microcontroller with two 32-bit
general-purpose I/O ports (Port 0 and Port 1). GPIO pins are controlled by
registers: PINSEL (Pin Function Select), IOxDIR (Direction register: 1 for
Output, 0 for Input), IOxSET (Set pin high), and IOxCLR (Clear pin low).
An LED connected in active-high or active-low configuration is toggled
with software delay loops. In this experiment, Port 0 pins (P0.10 - P0.17)
drive an 8-LED bar display, demonstrating single-pin blinking, alternating
blinking, and binary counter sequences.
============================================================================
*/

/*
 * Experiment 15: Interfacing 16x2 Alphanumeric LCD with LPC2148
 * 8-Bit Interface: Data on P0.0-P0.7, Control on P0.8(RS), P0.9(RW), P0.10(EN)
 */

#include <LPC214x.h>

#define LCD_DATA_PINS  0x000000FF  // P0.0 - P0.7
#define RS_PIN         (1U << 8)   // P0.8
#define RW_PIN         (1U << 9)   // P0.9
#define EN_PIN         (1U << 10)  // P0.10

void delay_lcd(unsigned int count) {
    unsigned int i, j;
    for (i = 0; i < count; i++)
        for (j = 0; j < 3000; j++);
}

void LCD_Command(unsigned char cmd) {
    IO0CLR = LCD_DATA_PINS | RS_PIN | RW_PIN;
    IO0SET = (cmd & 0xFF);
    IO0SET = EN_PIN;
    delay_lcd(2);
    IO0CLR = EN_PIN;
    delay_lcd(5);
}

void LCD_Data(unsigned char data_byte) {
    IO0CLR = LCD_DATA_PINS | RW_PIN;
    IO0SET = RS_PIN | (data_byte & 0xFF);
    IO0SET = EN_PIN;
    delay_lcd(2);
    IO0CLR = EN_PIN;
    delay_lcd(5);
}

void LCD_String(const char *str) {
    while (*str) {
        LCD_Data((unsigned char)*str++);
    }
}

void LCD_Init(void) {
    PINSEL0 &= ~0x001FFFFF;      // Configure P0.0 - P0.10 as GPIO
    IO0DIR |= (LCD_DATA_PINS | RS_PIN | RW_PIN | EN_PIN);

    LCD_Command(0x38);           // 8-bit mode, 2 lines, 5x7 dots
    LCD_Command(0x0C);           // Display ON, Cursor OFF
    LCD_Command(0x06);           // Increment cursor
    LCD_Command(0x01);           // Clear display screen
    delay_lcd(10);
}

int main(void) {
    LCD_Init();
    LCD_Command(0x80);           // Move cursor to Line 1
    LCD_String("LabX Embedded C");
    LCD_Command(0xC0);           // Move cursor to Line 2
    LCD_String("LPC2148 LCD OK");

    while (1) {
        // Static message display
    }
    return 0;
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
A 16x2 alphanumeric LCD display interfaces with the LPC2148 using 8 data
lines (D0-D7) and 3 control lines: RS (Register Select - 0 for command, 1
for data), RW (Read/Write - grounded for write), and EN (Enable -
high-to-low pulse to latch data). Commands initialize display mode (0x38
for 8-bit, 2-line mode), display ON cursor OFF (0x0C), clear screen
(0x01), and set DDRAM address (0x80 line 1, 0xC0 line 2). The LPC2148
drives the LCD by asserting RS, placing data on Port 0, and pulsing EN
with sufficient setup and hold time.
============================================================================
*/

/*
 * Experiment 16: Serial Communication between Controller Boards (UART0 on LPC2148)
 * Configures 9600 Baud, 8 Data Bits, 1 Stop Bit, No Parity (9600-8-N-1)
 */

#include <LPC214x.h>

void UART0_Init(void) {
    // Configure P0.0 as TXD0, P0.1 as RXD0
    PINSEL0 &= ~0x0000000F;
    PINSEL0 |= 0x00000005;

    // Enable Divisor Latch Access Bit (DLAB = 1)
    U0LCR = 0x83;

    // Set Baud Rate to 9600 for PCLK = 15 MHz (15000000 / (16 * 9600) = 97.65)
    U0DLM = 0x00;
    U0DLL = 97;

    // Disable DLAB and set 8-bit word length
    U0LCR = 0x03;

    // Enable and reset FIFO buffers
    U0FCR = 0x07;
}

void UART0_SendChar(char ch) {
    // Wait until Transmit Holding Register is Empty (THRE = bit 5)
    while (!(U0LSR & 0x20));
    U0THR = ch;
}

char UART0_ReceiveChar(void) {
    // Wait until Receiver Data Ready (RDR = bit 0)
    while (!(U0LSR & 0x01));
    return (char)U0RBR;
}

void UART0_SendString(const char *str) {
    while (*str) {
        UART0_SendChar(*str++);
    }
}

int main(void) {
    UART0_Init();
    UART0_SendString("\r\n==========================================\r\n");
    UART0_SendString(" LabX Remote: LPC2148 UART0 Communication\r\n");
    UART0_SendString(" Serial Port Initialized at 9600 Baud (8-N-1)\r\n");
    UART0_SendString("==========================================\r\n");
    UART0_SendString("Type characters in terminal to echo back:\r\n");

    while (1) {
        char ch = UART0_ReceiveChar();
        UART0_SendChar(ch);     // Echo back received character
        if (ch == '\r') {
            UART0_SendChar('\n');
        }
    }
    return 0;
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
LPC2148 features two asynchronous serial ports (UART0 and UART1). UART
communication requires setting the baud rate generator using U0LCR (Line
Control Register, DLAB=1), U0DLL, and U0DLM divider latches based on PCLK
(Peripheral Clock). Data transmission occurs by polling the Transmit
Holding Register Empty (THRE) flag in U0LSR and writing bytes to U0THR.
Data reception polls the Receiver Data Ready (RDR) flag and reads from
U0RBR. Setting word length to 8 bits, 1 stop bit, and no parity
establishes standard 9600-8-N-1 serial framing.
============================================================================
*/

#include <LPC214x.h>

#define LED       (1U << 10)   // P0.10
#define EINT0_PIN (1U << 16)   // P0.16

volatile unsigned int wakeup_flag = 0;

/* External Interrupt 0 service routine */
void eint0_isr(void) __irq
{
    EXTINT = 0x01;             // Clear EINT0 interrupt flag
    wakeup_flag = 1;

    VICVectAddr = 0x00;        // End of interrupt
}

void eint0_init(void)
{
    /* Configure P0.16 as EINT0 */
    PINSEL1 &= ~(3U << 0);
    PINSEL1 |=  (1U << 0);

    /* Configure EINT0 as edge-sensitive, falling edge */
    EXTMODE |= 0x01;
    EXTPOLAR &= ~0x01;
    EXTINT = 0x01;

    /* Configure VIC for EINT0 */
    VICIntSelect &= ~(1U << 14);
    VICVectAddr0 = (unsigned long)eint0_isr;
    VICVectCntl0 = 0x20 | 14;
    VICIntEnable |= (1U << 14);
}

int main(void)
{
    /* Configure P0.10 as GPIO output */
    PINSEL0 &= ~(3U << 20);
    IO0DIR |= LED;
    IO0CLR = LED;

    eint0_init();

    while (1)
    {
        if (wakeup_flag)
        {
            wakeup_flag = 0;
            IO0PIN ^= LED;     // Toggle LED after wake-up
        }

        /* Enter Idle Mode */
        PCON = 0x01;
    }
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
To implement power management techniques in the LPC2148 embedded
controller by configuring its power-saving modes to reduce power
consumption. Power management in the LPC2148 is controlled via the PCON
(Power Control) and PCONP (Power Control for Peripherals) registers.
LPC2148 supports Idle Mode (PCON=0x01) where the CPU clock stops while
peripherals continue running, and Power Down Mode (PCON=0x02) where both
CPU and oscillator are halted. An external interrupt (EINT0 on P0.16) is
configured via the Vectored Interrupt Controller (VIC) to wake the
microcontroller from low-power state, toggle a status LED, and resume
operation.
============================================================================
*/

/*
 * Experiment 18: Binary and Counting Semaphores for Task Synchronization in FreeRTOS
 * Demonstrates xSemaphoreCreateBinary and xSemaphoreCreateCounting on Arduino / AVR
 */

#include <Arduino_FreeRTOS.h>
#include <semphr.h>

SemaphoreHandle_t xBinarySemaphore;
SemaphoreHandle_t xCountingSemaphore;

void TaskProducer(void *pvParameters) {
    (void) pvParameters;
    int eventCount = 0;
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(1500));
        eventCount++;
        Serial.print("[Producer] Signaling Binary Event #");
        Serial.println(eventCount);
        xSemaphoreGive(xBinarySemaphore);

        // Also give counting token if space allows
        xSemaphoreGive(xCountingSemaphore);
    }
}

void TaskBinaryConsumer(void *pvParameters) {
    (void) pvParameters;
    for (;;) {
        if (xSemaphoreTake(xBinarySemaphore, portMAX_DELAY) == pdTRUE) {
            Serial.println("  --> [Binary Consumer] Acquired semaphore! Synchronized task executed.");
        }
    }
}

void TaskCountingWorker(void *pvParameters) {
    (void) pvParameters;
    for (;;) {
        if (xSemaphoreTake(xCountingSemaphore, pdMS_TO_TICKS(3000)) == pdTRUE) {
            Serial.println("  --> [Counting Worker] Shared resource accessed (Token acquired).");
            vTaskDelay(pdMS_TO_TICKS(400));
        } else {
            Serial.println("  --> [Counting Worker] Resource wait timeout.");
        }
    }
}

void setup() {
    Serial.begin(9600);
    while (!Serial) { ; }
    Serial.println("=== FreeRTOS Binary & Counting Semaphore Demo ===");

    xBinarySemaphore = xSemaphoreCreateBinary();
    xCountingSemaphore = xSemaphoreCreateCounting(3, 0);

    if (xBinarySemaphore != NULL && xCountingSemaphore != NULL) {
        xTaskCreate(TaskProducer, "Producer", 128, NULL, 2, NULL);
        xTaskCreate(TaskBinaryConsumer, "BinConsumer", 128, NULL, 1, NULL);
        xTaskCreate(TaskCountingWorker, "CountWorker", 128, NULL, 1, NULL);
    }
}

void loop() {
    // Empty: FreeRTOS scheduler manages execution
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
FreeRTOS is a lightweight open source Real time Operating system (RTOS)
made for use in embedded systems. It helps manage multiple tasks schedules
them properly allows tasks to work together smoothly and share resources
without conflict. Semaphores are synchronization mechanisms used to
coordinate tasks. A Binary Semaphore has a maximum count of 1, functioning
similarly to a mutex flag to signal events between tasks or ISRs using
xSemaphoreCreateBinary, xSemaphoreTake, and xSemaphoreGive. A Counting
Semaphore has a count >= 1 (xSemaphoreCreateCounting), tracking multiple
available units of a shared resource or counting events. When tasks take
the semaphore, the count decrements; when tasks release the resource, the
count increments.
============================================================================
*/

/*
 * Experiment 19: Porting FreeRTOS to Arduino UNO (ATmega328P) Development Board
 * Demonstrates Kernel Porting, Preemptive Task Scheduling & vTaskDelay()
 */

#include <Arduino_FreeRTOS.h>

#define LED_PIN_1 12
#define LED_PIN_2 13

void TaskBlink1(void *pvParameters) {
    (void) pvParameters;
    pinMode(LED_PIN_1, OUTPUT);
    for (;;) {
        digitalWrite(LED_PIN_1, HIGH);
        vTaskDelay(pdMS_TO_TICKS(250));
        digitalWrite(LED_PIN_1, LOW);
        vTaskDelay(pdMS_TO_TICKS(250));
        Serial.println("[Task 1] Fast Blink (250ms) - Priority 1");
    }
}

void TaskBlink2(void *pvParameters) {
    (void) pvParameters;
    pinMode(LED_PIN_2, OUTPUT);
    for (;;) {
        digitalWrite(LED_PIN_2, HIGH);
        vTaskDelay(pdMS_TO_TICKS(1000));
        digitalWrite(LED_PIN_2, LOW);
        vTaskDelay(pdMS_TO_TICKS(1000));
        Serial.println("[Task 2] Slow Heartbeat (1000ms) - Priority 1");
    }
}

void setup() {
    Serial.begin(9600);
    while (!Serial) { ; }
    Serial.println("=== FreeRTOS Arduino Porting & Multitasking Initialized ===");

    xTaskCreate(TaskBlink1, "FastBlink", 128, NULL, 1, NULL);
    xTaskCreate(TaskBlink2, "SlowBlink", 128, NULL, 1, NULL);
}

void loop() {
    // Arduino loop stays empty; RTOS scheduler handles tasks
}



/* --- Line 50: Execution & Theory Division --- */

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
FreeRTOS is a lightweight real-time operating system designed for embedded
systems with constrained memory footprint. Porting FreeRTOS to the
ATmega328P microcontroller on the Arduino UNO board allows developers to
run preemptive priority-based multitasking on an 8-bit platform. The
FreeRTOS kernel replaces the traditional single-threaded loop() construct
with independent task routines, each possessing its own stack, priority,
and state machine. Tasks yield control cooperatively using vTaskDelay(),
allowing the scheduler to context-switch to ready tasks.
============================================================================
*/

/*
 * Experiment 20: Creating Multiple Tasks using FreeRTOS on Arduino UNO
 * Demonstrates Priority-Based Preemption and Task State Transitions
 */

#include <Arduino_FreeRTOS.h>

void TaskHighPriority(void *pvParameters) {
    (void) pvParameters;
    for (;;) {
        Serial.println(">>> [HIGH PRIORITY TASK - 3] Critical execution cycle started.");
        vTaskDelay(pdMS_TO_TICKS(2000));
    }
}

void TaskMediumPriority(void *pvParameters) {
    (void) pvParameters;
    int reading = 0;
    for (;;) {
        reading = analogRead(A0);
        Serial.print("  [MED PRIORITY TASK - 2] Telemetry Sensor A0: ");
        Serial.println(reading);
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

void TaskLowPriority(void *pvParameters) {
    (void) pvParameters;
    unsigned long count = 0;
    for (;;) {
        count++;
        Serial.print("    [LOW PRIORITY TASK - 1] Background heartbeat tick: ");
        Serial.println(count);
        vTaskDelay(pdMS_TO_TICKS(500));
    }
}

void setup() {
    Serial.begin(9600);
    while (!Serial) { ; }
    Serial.println("=== FreeRTOS Multiple Tasks & Preemption Demonstration ===");

    xTaskCreate(TaskLowPriority,    "LowTask",  128, NULL, 1, NULL);
    xTaskCreate(TaskMediumPriority, "MedTask",  128, NULL, 2, NULL);
    xTaskCreate(TaskHighPriority,   "HighTask", 128, NULL, 3, NULL);
}

void loop() {
    // Managed by RTOS
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
Multitasking in FreeRTOS enables the concurrent execution of multiple
independent operational threads on a single core microcontroller. The
FreeRTOS preemptive scheduler enforces priority-based task switching,
ensuring that the highest priority ready task always gains execution
control. In this experiment, three distinct tasks (Sensor Reading Task,
Display/Telemetry Task, and Heartbeat Monitor Task) are instantiated with
varying priorities to demonstrate how priority inversion is avoided and
how tasks cleanly share CPU cycles.
============================================================================
*/

/*
 * Experiment 21: Real-Time Application IPC in FreeRTOS
 * Demonstrates Message Queues, Mutexes, and Event Groups for Inter-Task Messaging
 */

#include <Arduino_FreeRTOS.h>
#include <queue.h>
#include <semphr.h>

struct SensorPacket {
    int sensorId;
    int reading;
};

QueueHandle_t xSensorQueue;
SemaphoreHandle_t xSerialMutex;

void TaskProducer(void *pvParameters) {
    (void) pvParameters;
    struct SensorPacket packet;
    int counter = 0;
    for (;;) {
        counter++;
        packet.sensorId = 101;
        packet.reading = 50 + (counter % 30);

        if (xQueueSend(xSensorQueue, &packet, pdMS_TO_TICKS(100)) == pdPASS) {
            if (xSemaphoreTake(xSerialMutex, portMAX_DELAY) == pdTRUE) {
                Serial.print("[Producer] Sent packet #");
                Serial.print(counter);
                Serial.print(" Value: ");
                Serial.println(packet.reading);
                xSemaphoreGive(xSerialMutex);
            }
        }
        vTaskDelay(pdMS_TO_TICKS(800));
    }
}

void TaskConsumer(void *pvParameters) {
    (void) pvParameters;
    struct SensorPacket received;
    for (;;) {
        if (xQueueReceive(xSensorQueue, &received, portMAX_DELAY) == pdPASS) {
            if (xSemaphoreTake(xSerialMutex, portMAX_DELAY) == pdTRUE) {
                Serial.print("  --> [Consumer] Received Sensor: ");
                Serial.print(received.sensorId);
                Serial.print(" | Calibrated Data: ");
                Serial.println(received.reading * 1.5);
                xSemaphoreGive(xSerialMutex);
            }
        }
    }
}

void setup() {
    Serial.begin(9600);
    while (!Serial) { ; }
    Serial.println("=== FreeRTOS IPC: Queue, Mutex & Task Synchronization ===");

    xSensorQueue = xQueueCreate(5, sizeof(struct SensorPacket));
    xSerialMutex = xSemaphoreCreateMutex();

    if (xSensorQueue != NULL && xSerialMutex != NULL) {
        xTaskCreate(TaskProducer, "Producer", 128, NULL, 1, NULL);
        xTaskCreate(TaskConsumer, "Consumer", 128, NULL, 1, NULL);
    }
}

void loop() {
    // RTOS Managed
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
Inter-Process Communication (IPC) is a vital RTOS mechanism that allows
asynchronously executing tasks to safely exchange data and synchronization
events without memory corruption or race conditions. FreeRTOS provides
Message Queues (xQueueCreate, xQueueSend, xQueueReceive) for thread-safe
FIFO passing of data packets, Event Groups (xEventGroupCreate,
xEventGroupSetBits, xEventGroupWaitBits) for compound multi-task flag
synchronization, and Semaphores/Mutexes for mutually exclusive hardware
bus access. In this experiment, a producer task sends data packets through
a queue while an event group signals synchronization milestones.
============================================================================
*/

#include <LPC214x.h>

#define RED     (1U << 10)  // P0.10
#define YELLOW  (1U << 11)  // P0.11
#define GREEN   (1U << 12)  // P0.12

#define ALL_LEDS (RED | YELLOW | GREEN)

void delay(unsigned int count)
{
    unsigned int i, j;

    for (i = 0; i < count; i++)
        for (j = 0; j < 6000; j++);
}

void traffic_light(unsigned int signal)
{
    IO0CLR = ALL_LEDS;  // Turn OFF all LEDs
    IO0SET = signal;    // Turn ON selected LED
}

int main(void)
{
    // Select GPIO function for P0.10, P0.11 and P0.12
    PINSEL0 &= ~((3U << 20) |
                 (3U << 22) |
                 (3U << 24));

    // Configure LED pins as outputs
    IO0DIR |= ALL_LEDS;

    // Initially turn OFF all LEDs
    IO0CLR = ALL_LEDS;

    while (1)
    {
        // RED: Stop
        traffic_light(RED);
        delay(500);

        // GREEN: Go
        traffic_light(GREEN);
        delay(500);

        // YELLOW: Caution
        traffic_light(YELLOW);
        delay(200);
    }
}

/*
============================================================================
EXPERIMENT THEORY (from Embedded Systems & RTOS Laboratory Submission):
============================================================================
A traffic light control system is a type of embedded application that
helps manage how cars move through intersections. It uses red, yellow, and
green lights in a certain order to keep traffic moving safely and prevent
accidents. A real-time traffic light control system was created using the
LPC2148 embedded controller. GPIO pins were configured as outputs to
control the red, yellow, and green LEDs, and a programmed sequence was
executed using IO0DIR, IO0SET, and IO0CLR with calibrated delay routines.
============================================================================
*/

#include <stdio.h>
#include <string.h>

void divide(char data[], char gen[], int n, int m)
{
    for (int i = 0; i <= n - m; i++)
    {
        if (data[i] == '1')
        {
            for (int j = 0; j < m; j++)
            {
                data[i + j] =
                (data[i + j] == gen[j]) ? '0' : '1';
            }
        }
    }
}

int main()
{
    char data[256], gen[256];
    char temp[256], codeword[256];
    char received[256];

    int n, m, i;

    printf("Enter data bits: ");
    scanf("%255s", data);

    printf("Enter generator bits: ");
    scanf("%255s", gen);

    n = strlen(data);
    m = strlen(gen);

    if (n == 0 || m < 2 || n + m - 1 >= 256 || gen[0] != '1')
    {
        printf("Invalid input!\n");
        return 1;
    }

    for (i = 0; i < n; i++)
        if (data[i] != '0' && data[i] != '1')
            return printf("Invalid data!\n"), 1;

    for (i = 0; i < m; i++)
        if (gen[i] != '0' && gen[i] != '1')
            return printf("Invalid generator!\n"), 1;

    strcpy(temp, data);

    for (i = 0; i < m - 1; i++)
        temp[n + i] = '0';

    temp[n + m - 1] = '\0';

    divide(temp, gen, n + m - 1, m);

    strcpy(codeword, data);
    strncat(codeword, temp + n, m - 1);

    printf("\nCRC Remainder: %.*s\n", m - 1, temp + n);
    printf("Transmitted Codeword: %s\n", codeword);

    printf("\nEnter received codeword: ");
    scanf("%255s", received);

    if (strlen(received) != n + m - 1)
    {
        printf("Invalid codeword length!\n");
        return 1;
    }

    strcpy(temp, received);

    divide(temp, gen, n + m - 1, m);

    for (i = n; i < n + m - 1; i++)
        if (temp[i] != '0')
            break;

    if (i == n + m - 1)
        printf("No error detected.\n");
    else
        printf("Error detected.\n");

    return 0;
}

